import sqlite3
import json
import uuid
import struct
from typing import List

from fastapi import FastAPI, File, Form, UploadFile, HTTPException, Depends, Header, status
from fastapi.responses import Response

app = FastAPI()
DATABASE = "db.sqlite3"

def get_connection():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_connection()
    try:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS recipes (
                recipe_id TEXT PRIMARY KEY,
                owner_id TEXT NOT NULL,
                location_name TEXT NOT NULL,
                photo BLOB NOT NULL,
                authorized_viewers TEXT NOT NULL
            )
        """)
        conn.commit()
    finally:
        conn.close()

@app.on_event("startup")
def startup():
    init_db()

async def get_api_key(api_key: str = Header(..., alias="X-API-Key")) -> str:
    return api_key

def sanitize_png(data: bytes) -> bytes:
    # Verify PNG signature
    if data[:8] != b'\x89PNG\r\n\x1a\n':
        raise ValueError("Not a valid PNG image")
    chunks = []
    pos = 8
    while pos < len(data):
        if pos + 8 > len(data):
            raise ValueError("Incomplete chunk header")
        length = struct.unpack('>I', data[pos:pos+4])[0]
        chunk_type = data[pos+4:pos+8]
        chunk_data_start = pos + 8
        chunk_end = chunk_data_start + length + 4  # +4 for CRC
        if chunk_end > len(data):
            raise ValueError("Incomplete chunk data")
        chunk_bytes = data[pos:chunk_end]
        if chunk_type in (b'IHDR', b'PLTE', b'IDAT', b'IEND'):
            chunks.append((chunk_type, chunk_bytes))
        pos = chunk_end

    ihdr = None
    plte = None
    idats = []
    iend = None
    for ctype, cbytes in chunks:
        if ctype == b'IHDR':
            ihdr = cbytes
        elif ctype == b'PLTE':
            plte = cbytes
        elif ctype == b'IDAT':
            idats.append(cbytes)
        elif ctype == b'IEND':
            iend = cbytes

    if ihdr is None or iend is None:
        raise ValueError("Missing critical PNG chunks")

    out = bytearray(data[:8])  # PNG signature
    out.extend(ihdr)
    if plte:
        out.extend(plte)
    for idat in idats:
        out.extend(idat)
    out.extend(iend)
    return bytes(out)

@app.post("/recipes", status_code=201)
async def create_recipe(
    photo: UploadFile = File(...),
    locationName: str = Form(...),
    authorizedViewers: List[str] = Form(...),
    api_key: str = Depends(get_api_key)
):
    recipe_id = str(uuid.uuid4())
    photo_bytes = await photo.read()
    try:
        sanitized_photo = sanitize_png(photo_bytes)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    auth_json = json.dumps(authorizedViewers)
    conn = get_connection()
    try:
        conn.execute(
            "INSERT INTO recipes (recipe_id, owner_id, location_name, photo, authorized_viewers) VALUES (?, ?, ?, ?, ?)",
            (recipe_id, api_key, locationName, sanitized_photo, auth_json)
        )
        conn.commit()
    finally:
        conn.close()
    return {"recipeId": recipe_id}

@app.get("/recipes/{recipeId}")
def get_recipe(recipeId: str, api_key: str = Depends(get_api_key)):
    conn = get_connection()
    try:
        row = conn.execute("SELECT * FROM recipes WHERE recipe_id=?", (recipeId,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Recipe not found")
        owner_id = row["owner_id"]
        auth_list = json.loads(row["authorized_viewers"])
        if api_key != owner_id and api_key not in auth_list:
            raise HTTPException(status_code=404, detail="Recipe not found")
        photo_url = f"/recipes/{recipeId}/photo"
        recipe = {
            "recipeId": row["recipe_id"],
            "locationName": row["location_name"],
            "photoUrl": photo_url,
            "authorizedViewers": auth_list,
            "ownerId": owner_id
        }
        return recipe
    finally:
        conn.close()

@app.get("/recipes/{recipeId}/photo")
def get_photo(recipeId: str, api_key: str = Depends(get_api_key)):
    conn = get_connection()
    try:
        row = conn.execute("SELECT photo, owner_id, authorized_viewers FROM recipes WHERE recipe_id=?", (recipeId,)).fetchone()
        if row is None:
            raise HTTPException(status_code=404, detail="Recipe not found")
        owner_id = row["owner_id"]
        auth_list = json.loads(row["authorized_viewers"])
        if api_key != owner_id and api_key not in auth_list:
            raise HTTPException(status_code=404, detail="Recipe not found")
        photo_bytes = row["photo"]
    finally:
        conn.close()
    return Response(content=photo_bytes, media_type="image/png")

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=5000)
